import React, { useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";

const Checkout = () => {
  const cart = JSON.parse(sessionStorage.getItem("cart")) || [];
  const [form, setForm] = useState({ name: "", email: "", phone: "", address: "" });

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const submitOrder = async () => {
    const subtotal = cart.reduce((sum, item) => sum + parseFloat(item.price), 0);
    const total = (subtotal + subtotal * 0.08 + (Math.floor(Math.random() * 5) + 3)).toFixed(2);

    const res = await fetch(`${API_BASE_URL}/api/orders`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        user_id: sessionStorage.getItem("userId"),
        items: cart,
        total,
        shipping_info: { address: form.address },
        buyer_name: form.name,
        buyer_email: form.email,
        buyer_phone: form.phone
      })
    });

    if (res.ok) {
      alert("✅ Order placed!");
      sessionStorage.removeItem("cart");
      window.location.href = "/my-orders";
    } else {
      alert("❌ Order failed.");
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Navbar />
      <div className="p-4 flex-grow">
        <h2 className="text-xl font-bold mb-4">Checkout</h2>
        <input name="name" placeholder="Name" onChange={handleChange} className="block mb-2 p-2 border" />
        <input name="email" placeholder="Email" onChange={handleChange} className="block mb-2 p-2 border" />
        <input name="phone" placeholder="Phone" onChange={handleChange} className="block mb-2 p-2 border" />
        <input name="address" placeholder="Shipping Address" onChange={handleChange} className="block mb-2 p-2 border" />
        <button onClick={submitOrder} className="bg-green-500 text-white px-4 py-2 mt-2">Place Order</button>
      </div>
      <Footer />
    </div>
  );
};

export default Checkout;
